using System.Text.Json;
using EqlTracker.Core;

internal static class PetResearchTests
{
    internal static void Register(Action<string, Action> test)
    {
        void Check(bool ok) { if (!ok) throw new Exception("Pet research assertion failed"); }
        var at = new DateTime(2026, 10, 22, 12, 0, 0, DateTimeKind.Local);
        PetResearchContext Context() => new() { Pet = "Air", Summon = "Greater Conjuration: Air", Rank = 10, Level = 50, Patch = PetDefinition.Version, Equipment = "Reviewed gear", Buffs = "None", Targets = "Controlled target", Positioning = "Rear", FocusAndAA = "None", Complete = true };
        Encounter Fight() => new() { Id = "synthetic:1", Start = at, End = at.AddSeconds(10), Finished = true, PetName = "Mistling", PetType = "Air", PetDamage = 150, Events = [new() { Id = "1", Actor = "Mistling", Owner = "Pet", Time = at, Damage = 100, Ability = "slashes" }, new() { Id = "2", Actor = "Mistling", Owner = "Pet", Time = at.AddSeconds(5), Damage = 50, Ability = "Earthquake", Kind = "Spell" }] };
        test("Pet research: idempotent backfill preserves totals and encounter denominator", () => { var f = Fight(); string before = JsonSerializer.Serialize(f); var state = new PetResearchState(); Check(PetResearch.Collect(state, [f], new())); long revision = state.Revision; Check(!PetResearch.Collect(state, [f], new()) && revision == state.Revision); var s = state.Samples[f.Id]; Check(s.Damage == 150 && s.Seconds == 10 && s.Dps == 15 && s.Components.Values.Sum() == 150 && s.BuffPeriodDamage.Values.Sum() == 150 && s.BuffPeriodSeconds.Values.Sum() == 10 && before == JsonSerializer.Serialize(f)); });
        test("Pet research: all fields unknown by default and invalid HP retained separately", () => { var sheet = new PetStatSheet(); Check(PetResearch.StatFields.Length >= 40 && sheet.Values.Values.All(n => n == null)); sheet.Values["HP"] = -1; sheet.Values["Mana"] = 0; sheet.Validate(); Check(sheet.Values["HP"] == null && sheet.InvalidValues["HP"] == -1 && sheet.Values["Mana"] == 0 && sheet.Values["ResistPoison"] == null); });
        test("Pet research: cast does not establish active buff or 100 percent accuracy", () => { var state = new PetResearchState(); PetResearch.Observe(state, new() { Id = "cast", At = at, Actor = "Mistling", Spell = "Frenzied Burnout I", Transition = "Cast" }); Check(PetResearch.BuffPeriod(state.Buffs, "Mistling", at.AddSeconds(2)) == "Unresolved"); PetResearch.Collect(state, [Fight()], new()); Check(state.Samples.Values.Single().RecordedMisses == 0 && state.Samples.Values.Single().RecordedHitsPerSecond == .2); });
        test("Pet research: separate Burnout and Frenzied periods conserve original seconds", () => { var state = new PetResearchState(); foreach (var (id, spell, transition, seconds) in new[] { ("a", "Burnout III II", "Landing", 0), ("b", "Frenzied Burnout I", "Fade", 0), ("c", "Frenzied Burnout I", "Landing", 5) }) PetResearch.Observe(state, new() { Id = id, Actor = "Mistling", At = at.AddSeconds(seconds), Spell = spell, Transition = transition, DurationSeconds = 100 }); Check(PetResearch.BuffPeriod(state.Buffs, "Mistling", at.AddSeconds(2)) == "Burnout" && PetResearch.BuffPeriod(state.Buffs, "Mistling", at.AddSeconds(6)) == "Mixed"); PetResearch.Collect(state, [Fight()], new()); var s = state.Samples.Values.Single(); Check(s.BuffPeriodSeconds["Burnout"] == 5 && s.BuffPeriodSeconds["Mixed"] == 5 && s.BuffPeriodDamage.Values.Sum() == 150); });
        test("Pet research: missing fades after observed duration remain unresolved", () => { var buff = new PetBuffObservation { Actor = "Mistling", At = at, Spell = "Frenzied Burnout I", Transition = "Landing", DurationSeconds = 66 }; Check(PetResearch.BuffPeriod([buff], "Mistling", at.AddSeconds(70)) == "Unresolved"); });
        test("Pet research: landing correlation retains spell-line and upgrade identity without AA rank", () => { var state=new PetResearchState(); PetResearch.Observe(state,new(){Id="cast",Actor="Mistling",At=at,Spell="Burnout III II",Transition="Cast"}); Check(state.Buffs[0].SpellLine=="Burnout III"&&state.Buffs[0].UpgradeRank==2&&state.Buffs[0].AaRank==null); Check(PetResearch.ResolveBuffLanding(state,"Mistling",at.AddSeconds(6),["Burnout III I","Burnout III II"])=="Burnout III II"); PetResearch.Observe(state,new(){Id="fail",Actor="Mistling",At=at.AddSeconds(4),Spell="Burnout III II",Transition="Interrupted"}); Check(PetResearch.ResolveBuffLanding(state,"Mistling",at.AddSeconds(6),["Burnout III I","Burnout III II"]).Contains("unresolved")); });
        test("Pet research: corroborated procs and supported specials remain separate", () => { var state = new PetResearchState { Corrections = [new() { From = at, Until = at.AddHours(1), Context = Context(), ProcAbilities = ["Earthquake"], Evidence = "Synthetic reviewed proc" }] }; PetResearch.Collect(state, [Fight()], new()); Check(state.Samples.Values.Single().Components["Corroborated procs"] == 50 && state.Samples.Values.Single().Components["Melee"] == 100); });
        test("Pet research: absent details retain totals without inventing cadence", () => { var state = new PetResearchState(); var f = Fight(); f.Events.Clear(); f.DetailAvailable = false; PetResearch.Collect(state, [f], new()); var s = state.Samples.Values.Single(); Check(s.RecordedHits == 0 && !s.DetailComplete && s.Components.Values.Sum() == f.PetDamage); });
        test("Pet research: changed source replaces sample while preserving reviewed context", () => { var state = new PetResearchState(); var f = Fight(); PetResearch.Collect(state, [f], new()); state.Samples[f.Id].Reviewed = true; state.Samples[f.Id].Context = Context(); f.PetDamage = 170; PetResearch.Collect(state, [f], new()); Check(state.Samples.Count == 1 && state.Samples[f.Id].Damage == 170 && state.Samples[f.Id].Context.Complete); });
        test("Pet research: mismatched sample contexts and patches never blend", () => { var state = new PetResearchState(); var a = Fight(); var b = Fight(); b.Id = "b"; b.Start = at.AddDays(1); b.End = b.Start.AddSeconds(10); PetResearch.Collect(state, [a,b], new()); state.Samples[a.Id].Context = Context(); var summary = PetResearch.Summary(state, "Air"); Check(summary.Fights == 1 && !summary.Comparable); });
        PetCalibrationModel Model() => new() { Context = Context(), Trials = Enumerable.Range(1,4).Select(i => new PetCalibrationTrial { RunId = "r" + i, Holdout = i == 4, InputDelta = i * 10, OutputDelta = i * 120, BaselineRestored = true, Controlled = true, Evidence = "Synthetic ABA" }).ToList() };
        test("Pet research: repeat holdout and explicit review gates", () => { var m = Model(); Check(m.Gate == "Ready for explicit local review" && m.EstimateDelta(5, Context()) == null); m.LocallyApproved = true; m.ReviewEvidence = "Reviewed"; Check(m.Gate == "Validated locally" && m.EstimateDelta(5, Context()) == 60); var mismatch = Context(); mismatch.Rank = 9; Check(m.EstimateDelta(5, mismatch) == null); });
        test("Pet research: failed holdout duplicate IDs and incomplete controls block models", () => { var m = Model(); m.Trials[3].OutputDelta = 999; Check(m.Gate == "Training or holdout failed"); m = Model(); m.Trials[3].RunId = "r1"; Check(m.Gate.Contains("Distinct")); m = Model(); m.Trials[0].BaselineRestored = false; Check(m.Gate.Contains("Three")); m = Model(); m.Context.Patch = "Old"; Check(m.Gate.Contains("current-patch")); });
        test("Pet research: restart roundtrip preserves reviewed evidence and unknown resists", () => { var state = new PetResearchState { Sheets = [new() { Context = Context(), Reviewed = true }], Models = [Model()] }; var copy = JsonSerializer.Deserialize<PetResearchState>(JsonSerializer.Serialize(state))!; Check(copy.Sheets[0].Values["ResistMagic"] == null && copy.Models[0].Gate == "Ready for explicit local review"); });
        test("Pet research: delayed ownership associates a summon without unrelated NPC identity", () => { var profile = new CharacterProfile(); var detector = new PetElementDetector(); detector.Process(new() { Time = at, PlayerCast = "Greater Conjuration: Air X" }, profile); detector.Process(new() { Time = at.AddMinutes(2), PetActivity = "Unrelated" }, profile); Check(profile.PetIdentities.Count == 0); profile.PetIdentities.Add(new() { Name = "Mistling", From = at.AddMinutes(5) }); Check(detector.Process(new() { Time = at.AddMinutes(5), PetName = "Mistling" }, profile) && profile.EffectivePetElement == "Air"); });
        test("Pet research: failed summon never grants family and Monster rank suffix is recognized", () => { var profile = new CharacterProfile(); var detector = new PetElementDetector(); detector.Process(new() { Time = at, PlayerCast = "Monster Summoning II VIII" }, profile); detector.Process(new() { Time = at.AddSeconds(4), CastFailed = true, FailedSpell = "Monster Summoning II VIII" }, profile); profile.PetIdentities.Add(new() { Name = "Mistling", From = at.AddMinutes(1) }); detector.Process(new() { Time = at.AddMinutes(1), PetName = "Mistling" }, profile); Check(profile.EffectivePetElement == "Unknown" && PetElementDetector.SummonElement("Monster Summoning II VIII") == "Monster"); });
        test("Pet research: active unresolved pet blocks stale family and historical identity differs", () => { var profile = new CharacterProfile { PetIdentities = [new() { Name = "Mistling", From = at, Until = at.AddMinutes(2), Element = "Earth" }, new() { Name = "Mistling", From = at.AddMinutes(3) }] }; Check(profile.EffectivePetElement == "Unknown" && PetIdentityResolver.DisplayFamily(profile, [Fight()], true) == "Earth"); profile.PetIdentities[1].Element = "Air"; Check(profile.EffectivePetElement == "Air"); profile.PetElementOverride = "Water"; Check(profile.EffectivePetElement == "Water"); });
    }
}
